import truncbf = require( './index' );


// TESTS //

// The function returns a number...
{
	truncbf( 3.14, 2, 10 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument that is not a number...
{
	truncbf( true, 2, 10 ); // $ExpectError
	truncbf( false, 2, 10 ); // $ExpectError
	truncbf( '5', 2, 10 ); // $ExpectError
	truncbf( [], 2, 10 ); // $ExpectError
	truncbf( {}, 2, 10 ); // $ExpectError
	truncbf( ( x: number ): number => x, 2, 10 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument that is not a number...
{
	truncbf( 3.14, true, 10 ); // $ExpectError
	truncbf( 3.14, false, 10 ); // $ExpectError
	truncbf( 3.14, '5', 10 ); // $ExpectError
	truncbf( 3.14, [], 10 ); // $ExpectError
	truncbf( 3.14, {}, 10 ); // $ExpectError
	truncbf( 3.14, ( x: number ): number => x, 10 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument that is not a number...
{
	truncbf( 3.14, 2, true ); // $ExpectError
	truncbf( 3.14, 2, false ); // $ExpectError
	truncbf( 3.14, 2, '5' ); // $ExpectError
	truncbf( 3.14, 2, [] ); // $ExpectError
	truncbf( 3.14, 2, {} ); // $ExpectError
	truncbf( 3.14, 2, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	truncbf(); // $ExpectError
	truncbf( 3.14 ); // $ExpectError
	truncbf( 3.14, 2 ); // $ExpectError
}
